import{_ as o,a0 as r,w as p,s as d,I as i,x as e,a1 as a,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"更好利用 tmux 會話的 4 個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"更好利用 tmux 會話的 4 個技巧 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"更好利用 tmux 會話的 4 個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"更好利用 tmux 會話的 4 個技巧 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180827 4 tips for better tmux sessions","title":"更好利用 tmux 會話的 4 個技巧","tag":"201810","desc":""},"relativePath":"201810/20180827 4 tips for better tmux sessions.md","filePath":"[post].md"}'),u={name:"201810/20180827 4 tips for better tmux sessions.md"};function m(f,t,g,x,h,b){const s=r("Link");return p(),d("div",null,[t[26]||(t[26]=i("h1",{id:"更好利用-tmux-會話的-4-個技巧",tabindex:"-1"},[e("更好利用 tmux 會話的 4 個技巧 "),i("a",{class:"header-anchor",href:"#更好利用-tmux-會話的-4-個技巧","aria-label":"Permalink to “更好利用 tmux 會話的 4 個技巧”"},"​")],-1)),t[27]||(t[27]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/08/tmux-4-tips-816x345.jpg",alt:""})],-1)),i("p",null,[t[1]||(t[1]=e("tmux 是一個終端多路複用工具，它可以讓你係統上的終端支持多面板。你可以排列面板位置，在每個面板運行不同進程，這通常可以更好的地利用你的屏幕。我們在 ",-1)),a(s,{href:"https://fedoramagazine.org/use-tmux-more-powerful-terminal/"},{default:l(()=>[...t[0]||(t[0]=[e("這篇早期的文章",-1)])]),_:1}),t[2]||(t[2]=e(" 中向讀者介紹過這一強力工具。如果你已經開始使用 tmux 了，那麼這裏有一些技巧可以幫你更好地使用它。",-1))]),t[28]||(t[28]=n(`<p>本文假設你當前的前綴鍵是 <code>Ctrl+b</code>。如果你已重新映射該前綴，只需在相應位置替換為你定義的前綴即可。</p><h3 id="設置終端為自動使用-tmux" tabindex="-1">設置終端為自動使用 tmux <a class="header-anchor" href="#設置終端為自動使用-tmux" aria-label="Permalink to “設置終端為自動使用 tmux”">​</a></h3><p>使用 tmux 的一個最大好處就是可以隨意的從會話中斷開和重連。這使得遠程登錄會話功能更加強大。你有沒有遇到過丟失了與遠程系統的連接，然後好希望能夠恢復在遠程系統上做過的那些工作的情況？tmux 能夠解決這一問題。</p><p>然而，有時在遠程系統上工作時，你可能會忘記開啓會話。避免出現這一情況的一個方法就是每次通過交互式 shell 登錄系統時都讓 tmux 啓動或附加上一個會話。</p><p>在你遠程系統上的 <code>~/.bash_profile</code> 文件中加入下面內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -z &quot;$TMUX&quot; ]; then</span></span>
<span class="line"><span>    tmux attach -t default || tmux new -s default</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>然後註銷遠程系統，並使用 SSH 重新登錄。你會發現你處在一個名為 <code>default</code> 的 tmux 會話中了。如果退出該會話，則下次登錄時還會重新生成此會話。但更重要的是，若您正常地從會話中分離，那麼下次登錄時你會發現之前工作並沒有丟失 - 這在連接中斷時非常有用。</p><p>你當然也可以將這段配置加入本地系統中。需要注意的是，大多數 GUI 界面的終端並不會自動使用這個 <code>default</code> 會話，因此它們並不是登錄 shell。雖然你可以修改這一行為，但它可能會導致終端嵌套執行附加到 tmux 會話這一動作，從而導致會話不太可用，因此當進行此操作時請一定小心。</p><h3 id="使用縮放功能使注意力專注於單個進程" tabindex="-1">使用縮放功能使注意力專注於單個進程 <a class="header-anchor" href="#使用縮放功能使注意力專注於單個進程" aria-label="Permalink to “使用縮放功能使注意力專注於單個進程”">​</a></h3><p>雖然 tmux 的目的就是在單個會話中提供多窗口、多面板和多進程的能力，但有時候你需要專注。如果你正在與一個進程進行交互並且需要更多空間，或需要專注於某個任務，則可以使用縮放命令。該命令會將當前面板擴展，佔據整個當前窗口的空間。</p><p>縮放在其他情況下也很有用。比如，想像你在圖形桌面上運行一個終端窗口。面板會使得從 tmux 會話中拷貝和粘帖多行內容變得相對困難。但若你縮放了面板，就可以很容易地對多行數據進行拷貝/粘帖。</p><p>要對當前面板進行縮放，按下 <code>Ctrl+b, z</code>。需要恢復的話，按下相同按鍵組合來恢復面板。</p><h3 id="綁定一些有用的命令" tabindex="-1">綁定一些有用的命令 <a class="header-anchor" href="#綁定一些有用的命令" aria-label="Permalink to “綁定一些有用的命令”">​</a></h3><p>tmux 默認有大量的命令可用。但將一些更常用的操作綁定到容易記憶的快捷鍵會很有用。下面一些例子可以讓會話變得更好用，你可以添加到 <code>~/.tmux.conf</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bind r source-file ~/.tmux.conf \\; display &quot;Reloaded config&quot;</span></span></code></pre></div><p>該命令重新讀取你配置文件中的命令和鍵綁定。添加該條綁定後，退出任意一個 tmux 會話然後重啓一個會話。現在你做了任何更改後，只需要簡單的按下 <code>Ctrl+b, r</code> 就能將修改的內容應用到現有的會話中了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bind V split-window -h</span></span>
<span class="line"><span>bind H split-window</span></span></code></pre></div><p>這些命令可以很方便地對窗口進行橫向切分（按下 <code>Shift+V</code>）和縱向切分（<code>Shift+H</code>）。</p><p>若你想查看所有綁定的快捷鍵，按下 <code>Ctrl+B, ?</code> 可以看到一個列表。你首先看到的應該是複製模式下的快捷鍵綁定，表示的是當你在 tmux 中進行復制粘帖時對應的快捷鍵。你添加的那兩個鍵綁定會在<ruby>前綴模式<rt>prefix mode</rt></ruby>中看到。請隨意把玩吧！</p><h3 id="使用-powerline-更清晰" tabindex="-1">使用 powerline 更清晰 <a class="header-anchor" href="#使用-powerline-更清晰" aria-label="Permalink to “使用 powerline 更清晰”">​</a></h3>`,20)),i("p",null,[a(s,{href:"https://fedoramagazine.org/add-power-terminal-powerline/"},{default:l(()=>[...t[3]||(t[3]=[e("如前文所示",-1)])]),_:1}),t[4]||(t[4]=e("，powerline 工具是對 shell 的絕佳補充。而且它也兼容在 tmux 中使用。由於 tmux 接管了整個終端空間，powerline 窗口能提供的可不僅僅是更好的 shell 提示那麼簡單。",-1))]),i("p",null,[a(s,{href:"https://fedoramagazine.org/wp-content/uploads/2018/08/Screenshot-from-2018-08-25-19-36-53.png"},{default:l(()=>[...t[5]||(t[5]=[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/08/Screenshot-from-2018-08-25-19-36-53-1024x690.png",alt:"Screenshot of tmux powerline in git folder"},null,-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=e("如果你還沒有這麼做，按照 ",-1)),a(s,{href:"https://fedoramagazine.org/add-power-terminal-powerline/"},{default:l(()=>[...t[6]||(t[6]=[e("這篇文章",-1)])]),_:1}),t[9]||(t[9]=e(" 中的指示來安裝該工具。然後",-1)),a(s,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:l(()=>[...t[7]||(t[7]=[e("使用 sudo",-1)])]),_:1}),t[10]||(t[10]=e(" 來安裝附件：",-1))]),t[29]||(t[29]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install tmux-powerline</span></span></code></pre></div><p>接着重啓會話，就會在底部看到一個漂亮的新狀態欄。根據終端的寬度，默認的狀態欄會顯示你當前會話 ID、打開的窗口、系統信息、日期和時間，以及主機名。若你進入了使用 git 進行版本控制的項目目錄中還能看到分支名和用色彩標註的版本庫狀態。</p><p>當然，這個狀態欄具有很好的可配置性。享受你新增強的 tmux 會話吧，玩的開心點。</p><hr>',4)),i("p",null,[t[12]||(t[12]=e("via: ",-1)),a(s,{href:"https://fedoramagazine.org/4-tips-better-tmux-sessions/"},{default:l(()=>[...t[11]||(t[11]=[e("https://fedoramagazine.org/4-tips-better-tmux-sessions/",-1)])]),_:1})]),i("p",null,[t[17]||(t[17]=e("作者：",-1)),a(s,{href:"https://fedoramagazine.org/author/pfrields/"},{default:l(()=>[...t[13]||(t[13]=[e("Paul W. Frields",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[14]||(t[14]=[e("lujun9972",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[15]||(t[15]=[e("lujun9972",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[23]||(t[23]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:l(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const w=o(u,[["render",m]]);export{T as __pageData,w as default};
